// Cyrus one-account bridge: which hostnames are "the Cyrus app" and where each side lives. PURE (Edge-safe: the
// middleware imports it), HOST SEAM: no Nxeon imports.
//
//   CYRUS_DOMAIN_MODE=1        the switch. Off (default) = nothing in this folder changes any request.
//   CYRUS_HOSTS                comma list of Cyrus hostnames (default "cyrus.my,www.cyrus.my")
//   CYRUS_ORIGIN               the Cyrus app origin (default https://<first CYRUS_HOSTS entry>)
//   APP_URL                    the Nxeon origin (the identity provider + wallet), as everywhere else
export type BridgeConfig = { enabled: boolean; cyrusHosts: string[]; cyrusOrigin: string; nxeonOrigin: string };

const trimSlash = (s: string) => s.replace(/\/+$/, "");

export function bridgeConfig(env: Record<string, string | undefined> = process.env): BridgeConfig {
  const hosts = (env.CYRUS_HOSTS ?? "cyrus.my,www.cyrus.my").split(",").map((h) => h.trim().toLowerCase()).filter(Boolean);
  return {
    enabled: env.CYRUS_DOMAIN_MODE === "1" && hosts.length > 0,
    cyrusHosts: hosts,
    cyrusOrigin: trimSlash(env.CYRUS_ORIGIN || `https://${hosts[0] ?? "cyrus.my"}`),
    nxeonOrigin: trimSlash(env.APP_URL || "https://nxeon.cloud"),
  };
}

/** True only with the mode on AND an exact (port-less, lower-cased) hostname match. */
export function isCyrusHost(host: string | null | undefined, cfg: BridgeConfig = bridgeConfig()): boolean {
  if (!cfg.enabled || !host) return false;
  return cfg.cyrusHosts.includes(host.toLowerCase().split(":")[0]);
}

/** The request header middleware sets on Cyrus-host requests (and strips from every incoming request). */
export const CYRUS_HOST_HEADER = "x-cyrus-host";

/** Session cookie on the Cyrus host. `__Host-` in production: Secure, path=/, no Domain, so it can never be
 *  scoped to a parent domain or set by a sibling host. */
export const cyrusSessionCookie = (env: Record<string, string | undefined> = process.env) =>
  env.NODE_ENV === "production" ? "__Host-cyrus_session" : "cyrus_session";
/** The short-lived sign-in state cookie (state + nonce + next) on whichever host started a handshake. */
export const ssoStateCookie = (side: "cyrus" | "nxeon", env: Record<string, string | undefined> = process.env) =>
  `${env.NODE_ENV === "production" ? "__Host-" : ""}${side}_sso_state`;

/** The fixed callback URLs. Exact-match only: no prefixes, no query, so redirect_uri can never point elsewhere. */
export const callbackUrls = (cfg: BridgeConfig = bridgeConfig()) => ({
  cyrus: `${cfg.cyrusOrigin}/auth/nxeon/callback`,
  nxeon: `${cfg.nxeonOrigin}/sso/cyrus/return`,
});
  }
}

/* -------------------------------------------------------------------------- */
/*                       Who is being rate limited                            */
/* -------------------------------------------------------------------------- */

/**
 * How many reverse proxies sit in front of this app and append to
 * `X-Forwarded-For`. ONE (nginx) for every current Nxeon deployment.
 *
 * Raise it only when you actually add another trusted hop that APPENDS to the
 * header without nginx restoring the client first. Cloudflare does NOT need a
 * raise: nginx's real_ip module (deploy/cloudflare/nginx/cloudflare-realip.conf)
 * turns $remote_addr back into the visitor from CF-Connecting-IP, so the last
 * hop and X-Real-IP are already the visitor (proven by
 * scripts/cloudflare/test-realip.sh). Raising it there would trust a hop a
 * direct-to-origin caller can write. Setting it higher than the number of proxies you really run walks the
 * trusted suffix backwards into entries the CLIENT wrote, which is the exact bug
 * this function exists to fix. Setting it lower behind a CDN collapses every
 * visitor onto the edge's address, which turns a per-attacker throttle into a
 * global one — a login lockout for every customer at once.
 */
const TRUSTED_PROXY_HOPS = Math.max(1, Number(process.env.NXEON_TRUSTED_PROXY_HOPS ?? 1) || 1);

/** `unknown` is the shared bucket for callers we cannot place. */
export const UNKNOWN_IP = "unknown";

/**
 * Strip an optional `:port` / `[v6]:port` wrapper and an IPv4-mapped IPv6 prefix
 * so the same peer always produces the same bucket key. `::ffff:127.0.0.1` and
 * `127.0.0.1` are one machine; without this they are two budgets.
 */
function normaliseAddress(value: string): string {
  let v = value.trim();
  if (v.startsWith("[")) {
    const end = v.indexOf("]");
    if (end !== -1) v = v.slice(1, end);
  } else if (v.includes(":") && net.isIP(v) === 0) {
    // host:port for IPv4 (a bare IPv6 has many colons and parses as an IP).
    v = v.split(":")[0];
  }
  const mapped = /^::ffff:((?:\d{1,3}\.){3}\d{1,3})$/i.exec(v);
  return mapped ? mapped[1] : v;
}

/** Anything with a `.get()`: `await headers()`, `req.headers`, or a `Request`. */
type HeaderLike = { get(name: string): string | null };
export type ClientIpSource = HeaderLike | { headers: HeaderLike };

function headersOf(source: ClientIpSource): HeaderLike {
  return typeof (source as HeaderLike)?.get === "function"
    ? (source as HeaderLike)
    : (source as { headers: HeaderLike }).headers;
}

/**
 * The caller's address, for use as a rate-limit key. NEVER attacker-controlled.
 *
 * ── THIS IS THE ONLY DEFINITION ──────────────────────────────────────────────
 *
 * There were two. This one owned the trusted-hop knob; `trustedClientIp` in
 * app/api/_lib/client-ip.ts owned IP-format validation and `::ffff:`/port
 * normalisation. Each was correct about something the other got wrong, they were
 * written days apart from the same incident, and a reader had no way to know
 * which one their call site should use. A second definition of an existing thing
 * is this repo's most common defect class and it caused two production bugs in
 * one week, so the two have been merged here and `trustedClientIp` is now an
 * alias for this function — same code, two names, because ~15 route handlers
 * import it under the second one.
 *
 * Accepts a `Request` as well as a headers object so route handlers and server
 * actions call the same function rather than each growing a wrapper.
 *
 * WHY THIS IS NOT `xff.split(",")[0]`, which is what every call site used to do
 * (and what two route handlers still described in a comment as "the real
 * client"). nginx forwards the header as:
 *
 *     proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
 *
 * and `$proxy_add_x_forwarded_for` expands to `$http_x_forwarded_for,
 * $remote_addr` — it APPENDS the peer it actually saw to whatever the client
 * sent. So the header this app receives is:
 *
 *     <anything the client typed>, <the client's real address>
 *
 * The LEFTMOST entry is therefore not the client, it is a free-text field the
 * client filled in. Reading it made every limiter keyed on "the IP" evadable by
 * sending a different fake value each request — and that is not a theoretical
 * grading of a header, it was measured: 25 requests through the real nginx with a
 * rotating `X-Forwarded-For` never once tripped a limit that a fixed value trips
