export function clientIp(source: ClientIpSource): string {
  const h = headersOf(source);
  const hops = (h.get("x-forwarded-for") ?? "")
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
  if (hops.length > 0) {
    // Walk back past the proxies we run. Clamped at 0 so a misconfigured hop
    // count degrades to "the leftmost entry" instead of throwing, and keep
    // walking left while the entry is not a valid address — a junk value at the
    // trusted position must not become a bucket key of its own.
    for (let i = Math.max(0, hops.length - TRUSTED_PROXY_HOPS); i >= 0; i--) {
      const candidate = normaliseAddress(hops[i]);
      if (net.isIP(candidate) !== 0) return candidate;
    }
  }
  // `x-real-ip` is set with `proxy_set_header X-Real-IP $remote_addr`, which
  // REPLACES any client value rather than appending — an equally sound source.
  const real = normaliseAddress(h.get("x-real-ip") ?? "");
  if (net.isIP(real) !== 0) return real;
  return UNKNOWN_IP;
}

