// Which database Cyrus' own tables live in (data split, docs/CYRUS-PLATFORM.md section 4). Pure: no imports, no I/O.
// Unset (today): the host's database, exactly as before. Set: a separate Postgres for the Cyrus tables only; the host
// keeps its own tables (users, wallet, servers, settings) in its database and Cyrus reaches them through the seam.
// Rollback = unset it and restart. Never put this value in the browser bundle (it is a secret; only server code reads it).
type Env = Record<string, string | undefined>;

export function cyrusDatabaseUrl(env: Env = typeof process !== "undefined" ? process.env : {}): string | null {
  const v = env.CYRUS_DATABASE_URL?.trim();
  if (!v) return null;
  if (!/^postgres(ql)?:\/\//.test(v)) throw new Error("CYRUS_DATABASE_URL must be a postgres:// URL");
  if (env.DATABASE_URL && v === env.DATABASE_URL.trim()) return null; // same database: nothing is split
  return v;
}
