import { safeGrantPurchase, safeGrantRenewal, safeReverseServerGrants } from "../cyrus/tokens/grants";
import { emitPlatformEvent, serverPurchased, serverRefunded, serverRenewed } from "./events";

export async function cyrusServerPurchased(a: { userId: string; serverId: string; gameFamily?: string | null; chargeCents: number; termMonths: number }): Promise<void> {
  await safeGrantPurchase(a);
  await emitPlatformEvent(serverPurchased({ ...a, gameFamily: a.gameFamily ?? null })).catch(() => false);
}

export async function cyrusServerRenewed(a: { userId: string; serverId: string; gameFamily?: string | null; netCents: number; months: number; periodStart: Date }): Promise<void> {
  await safeGrantRenewal(a);
  await emitPlatformEvent(serverRenewed({ ...a, gameFamily: a.gameFamily ?? null })).catch(() => false);
}

/** A refunded server invoice: the server's unspent free tokens are taken back (never below zero). */
export async function cyrusServerRefunded(a: { userId: string; serverId: string; ref: string; cents: number }): Promise<void> {
  await safeReverseServerGrants({ userId: a.userId, serverId: a.serverId, reason: "refund", ref: a.ref });
  await emitPlatformEvent(serverRefunded(a)).catch(() => false);
}
