// NXEON SIDE: Nxeon -> Cyrus events through a signed transactional OUTBOX (the same shape and retry ladder as Cyrus'
// own webhooks from API phase 2, lib/cyrus/api/v1/webhooks.ts, mirrored in the other direction):
//   headers  Nxeon-Webhook-Id, Nxeon-Webhook-Timestamp (unix s), Nxeon-Signature: v1=<hex HMAC-SHA256(secret, id.ts.body)>
//   delivery at-least-once; 2xx = done; otherwise retried after 1 m, 5 m, 30 m, 2 h, 12 h, then DEAD (kept for replay).
//            Each event carries current state, never a delta; ids are deterministic so a double emit is one event.
//   events   server.version_changed, server.deleted, server.restarted, grant.created, grant.updated, grant.revoked,
//            entitlement.changed
// OFF unless CYRUS_PLATFORM_EVENTS=1 + CYRUS_PLATFORM_EVENTS_URL + CYRUS_PLATFORM_EVENTS_SECRET (>= 32 chars, never
// AUTH_SECRET). Outbox: memory (one instance) unless CYRUS_PLATFORM_EVENTS_STORE=sql ("CyrusPlatformOutbox" in
// prisma/manual-migration-cyrus-bridge-grants.sql, NOT run). The worker's "cyrus-platform-events" sweep dispatches.
// Imports nothing from lib/cyrus. SERVER ONLY.
import { createHmac } from "node:crypto";
import type { PlatformEvent } from "./api";
import type { Entitlement } from "./entitlement-schema";
import type { GrantEventSink, Sql } from "./grants";

export const PLATFORM_EVENT_TYPES = ["server.version_changed", "server.deleted", "server.restarted", "grant.created", "grant.updated", "grant.revoked", "entitlement.changed", "server.purchased", "server.renewed", "server.refunded"] as const;
export type PlatformEventType = (typeof PLATFORM_EVENT_TYPES)[number];
export type PlatformEnvelope<D = Record<string, unknown>> = { id: string; type: PlatformEventType; createdAt: string; subject: string | null; data: D };
export type OutboxRow = { id: string; type: string; subject: string | null; body: string; attempts: number; nextAttemptAt: Date; status: "pending" | "sent" | "dead"; lastError: string | null; createdAt: Date };
export const RETRY_MS = [60_000, 5 * 60_000, 30 * 60_000, 2 * 3600_000, 12 * 3600_000] as const;

export interface EventOutbox {
  add(e: PlatformEnvelope): Promise<void>;
  due(now: Date, limit: number): Promise<OutboxRow[]>;
  markSent(id: string, now: Date): Promise<void>;
  markFailed(id: string, a: { attempts: number; nextAttemptAt: Date | null; error: string }): Promise<void>;
}

export type EventTarget = { url: string; secret: string };
export function platformEventTarget(env: Record<string, string | undefined> = process.env): EventTarget | null {
  if (env.CYRUS_PLATFORM_EVENTS !== "1") return null;
  const url = env.CYRUS_PLATFORM_EVENTS_URL?.trim() ?? "", secret = env.CYRUS_PLATFORM_EVENTS_SECRET ?? "";
  if (!/^https?:\/\/\S+$/.test(url) || secret.length < 32 || secret === env.AUTH_SECRET) return null; // fail closed
  return { url, secret };
}
export const signPlatformEvent = (secret: string, id: string, ts: string, body: string) => `v1=${createHmac("sha256", secret).update(`${id}.${ts}.${body}`).digest("hex")}`;

// ------------------------------------------------------------------------------------------------ builders
const clean = (s: string) => s.replace(/[^A-Za-z0-9_-]/g, "").slice(0, 60);
function envelope<D extends Record<string, unknown>>(type: PlatformEventType, subject: string | null, data: D, at: Date, id: string): PlatformEnvelope<D> {
  return { id, type, createdAt: at.toISOString(), subject, data };
}
export const serverVersionChanged = (a: { userId: string; serverId: string; from: string | null; to: string | null; loader: string | null; at?: Date }) => {
  const at = a.at ?? new Date();
  return envelope("server.version_changed", a.userId, { serverId: a.serverId, from: a.from, to: a.to, loader: a.loader }, at, `evt_srvver_${clean(a.serverId)}_${clean(a.to ?? "none")}_${at.getTime()}`);
};
export const serverDeleted = (a: { userId: string; serverId: string; at?: Date }) =>
  envelope("server.deleted", a.userId, { serverId: a.serverId }, a.at ?? new Date(), `evt_srvdel_${clean(a.serverId)}`);
export const serverRestarted = (e: PlatformEvent) =>
  envelope("server.restarted", e.userId, { serverId: e.serverId, by: e.by }, e.at, `evt_srvrst_${clean(e.serverId)}_${e.at.getTime()}`);
export const grantChanged = (type: "grant.created" | "grant.updated" | "grant.revoked", g: { id: string; userId: string; serverId: string; scopes: string[]; revokedBy?: string | null }, at: Date) =>
  envelope(type, g.userId, { grantId: g.id, serverId: g.serverId, scopes: g.scopes, ...(type === "grant.revoked" ? { reason: g.revokedBy ?? "user" } : {}) }, at, `evt_${type.replace(".", "_")}_${clean(g.id)}_${at.getTime()}`);
// r41: the money events Cyrus' free server tokens follow (Cyrus grants/reverses idempotently per server + period/ref).
export const serverPurchased = (a: { userId: string; serverId: string; gameFamily: string | null; chargeCents: number; termMonths: number; at?: Date }) =>
  envelope("server.purchased", a.userId, { serverId: a.serverId, gameFamily: a.gameFamily, chargeCents: a.chargeCents, termMonths: a.termMonths }, a.at ?? new Date(), `evt_srvbuy_${clean(a.serverId)}`);
export const serverRenewed = (a: { userId: string; serverId: string; gameFamily: string | null; netCents: number; months: number; periodStart: Date; at?: Date }) =>
  envelope("server.renewed", a.userId, { serverId: a.serverId, gameFamily: a.gameFamily, netCents: a.netCents, months: a.months, periodStart: a.periodStart.toISOString() }, a.at ?? new Date(), `evt_srvrenew_${clean(a.serverId)}_${a.periodStart.getTime()}`);
export const serverRefunded = (a: { userId: string; serverId: string; ref: string; cents: number; at?: Date }) =>
  envelope("server.refunded", a.userId, { serverId: a.serverId, ref: a.ref, cents: a.cents }, a.at ?? new Date(), `evt_srvrefund_${clean(a.serverId)}_${clean(a.ref)}`);
export const entitlementChanged = (e: Entitlement) =>
  envelope("entitlement.changed", e.subject, e as unknown as Record<string, unknown>, new Date(e.issuedAt), `evt_ent_${clean(e.subject)}_${e.version}`);

// ------------------------------------------------------------------------------------------------ outboxes
export function createMemoryEventOutbox(): EventOutbox & { rows: Map<string, OutboxRow> } {
  const rows = new Map<string, OutboxRow>();
  return {
    rows,
    async add(e) { if (!rows.has(e.id)) rows.set(e.id, { id: e.id, type: e.type, subject: e.subject, body: JSON.stringify(e), attempts: 0, nextAttemptAt: new Date(e.createdAt), status: "pending", lastError: null, createdAt: new Date(e.createdAt) }); },
    async due(now, limit) { return [...rows.values()].filter((r) => r.status === "pending" && r.nextAttemptAt <= now).sort((a, b) => +a.createdAt - +b.createdAt).slice(0, limit); },
    async markSent(id) { const r = rows.get(id); if (r) { r.status = "sent"; r.lastError = null; } },
    async markFailed(id, f) { const r = rows.get(id); if (!r) return; r.attempts = f.attempts; r.lastError = f.error; if (f.nextAttemptAt) r.nextAttemptAt = f.nextAttemptAt; else r.status = "dead"; },
  };
}
export function createSqlEventOutbox(sql: Sql): EventOutbox {
  const T = `"CyrusPlatformOutbox"`;
  return {
    async add(e) { await sql.exec(`INSERT INTO ${T} (id, type, subject, body, next_attempt_at, created_at) VALUES ($1,$2,$3,$4,$5,$5) ON CONFLICT (id) DO NOTHING`, e.id, e.type, e.subject, JSON.stringify(e), new Date(e.createdAt)); },
    async due(now, limit) {
      // one dispatcher at a time is assumed (the worker sweep); a multi-worker setup claims rows in a transaction
      const rows = await sql.query<{ id: string; type: string; subject: string | null; body: string; attempts: number; next_attempt_at: Date; status: string; last_error: string | null; created_at: Date }>(
        `SELECT id, type, subject, body, attempts, next_attempt_at, status, last_error, created_at FROM ${T} WHERE status = 'pending' AND next_attempt_at <= $1 ORDER BY created_at ASC LIMIT $2`, now, limit);
      return rows.map((r) => ({ id: r.id, type: r.type, subject: r.subject, body: r.body, attempts: Number(r.attempts), nextAttemptAt: new Date(r.next_attempt_at), status: r.status as OutboxRow["status"], lastError: r.last_error, createdAt: new Date(r.created_at) }));
    },
    async markSent(id) { await sql.exec(`UPDATE ${T} SET status = 'sent', last_error = NULL WHERE id = $1`, id); },
    async markFailed(id, f) { await sql.exec(`UPDATE ${T} SET attempts = $2, last_error = $3, next_attempt_at = COALESCE($4::timestamptz, next_attempt_at), status = CASE WHEN $4::timestamptz IS NULL THEN 'dead' ELSE 'pending' END WHERE id = $1`, id, f.attempts, f.error, f.nextAttemptAt); },
  };
}

// ------------------------------------------------------------------------------------------------ dispatch
export async function dispatchPlatformEvents(a: { outbox: EventOutbox; target: EventTarget; now?: () => Date; fetch?: typeof fetch; limit?: number }): Promise<{ sent: number; retried: number; dead: number }> {
  const now = a.now ?? (() => new Date());
  const f = a.fetch ?? fetch;
  const out = { sent: 0, retried: 0, dead: 0 };
  for (const row of await a.outbox.due(now(), a.limit ?? 50)) {
    const ts = String(Math.floor(now().getTime() / 1000));
    let error: string | null = null;
    try {
      const res = await f(a.target.url, {
        method: "POST", body: row.body, redirect: "manual", signal: AbortSignal.timeout(10_000),
        headers: { "content-type": "application/json", "nxeon-webhook-id": row.id, "nxeon-webhook-timestamp": ts, "nxeon-signature": signPlatformEvent(a.target.secret, row.id, ts, row.body), "user-agent": "nxeon-platform-events/1" },
      });
      if (res.status < 200 || res.status >= 300) error = `HTTP ${res.status}`;
    } catch (e) { error = (e as Error).message || "network"; }
    if (!error) { await a.outbox.markSent(row.id, now()); out.sent++; continue; }
    const attempts = row.attempts + 1;
    const delay = RETRY_MS[attempts - 1];
    await a.outbox.markFailed(row.id, { attempts, nextAttemptAt: delay === undefined ? null : new Date(now().getTime() + delay), error: error.slice(0, 300) });
    if (delay === undefined) out.dead++; else out.retried++;
  }
  return out;
}

// ------------------------------------------------------------------------------------------------ process-wide
let shared: EventOutbox | null = null;
export function setEventOutboxForTests(o: EventOutbox | null) { shared = o; }
export async function eventOutbox(e: Record<string, string | undefined> = process.env): Promise<EventOutbox> {
  if (shared) return shared;
  if (e.CYRUS_PLATFORM_EVENTS_STORE === "sql") {
    const { db } = await import("../db");
    shared = createSqlEventOutbox({ query: (q, ...a) => db.$queryRawUnsafe(q, ...a), exec: (q, ...a) => db.$executeRawUnsafe(q, ...a) });
  } else shared = createMemoryEventOutbox();
  return shared;
}
/** Queue an event when events are on. Never throws into the caller's flow. */
export async function emitPlatformEvent(e: PlatformEnvelope, env: Record<string, string | undefined> = process.env): Promise<boolean> {
  if (!platformEventTarget(env)) return false;
  try { await (await eventOutbox(env)).add(e); return true; } catch (err) { console.error("[platform-events] outbox add failed", e.type, (err as Error).message); return false; }
}
/** The worker sweep: one dispatch pass (no-op while off). */
export async function platformEventsSweep(env: Record<string, string | undefined> = process.env) {
  const t = platformEventTarget(env);
  if (!t) return { sent: 0, retried: 0, dead: 0 };
  return dispatchPlatformEvents({ outbox: await eventOutbox(env), target: t });
}

/** The sink grant changes report to, or undefined when Nxeon -> Cyrus events are off. */
export function platformEventSink(env: Record<string, string | undefined> = process.env): GrantEventSink | undefined {
  if (!platformEventTarget(env)) return undefined;
  return async (e) => { await emitPlatformEvent(grantChanged(e.type, e.grant, e.at), env); };
}
/** The sink the Platform API reports server.restarted to, or undefined when events are off. */
export function platformEventSinkForApi(env: Record<string, string | undefined> = process.env): ((e: PlatformEvent) => Promise<void>) | undefined {
  if (!platformEventTarget(env)) return undefined;
  return async (e) => { await emitPlatformEvent(serverRestarted(e), env); };
}

