// to the page, and it does NOT count as activity, so the 10-minute idle rule is unchanged. No other behaviour changes:
// a missing pong closes nothing.
export function wsPingIntervalMs(env: Record<string, string | undefined>, name: string): number {
  const raw = env[name] ?? env.WS_KEEPALIVE_MS;
  const n = Number(raw);
  return raw && Number.isInteger(n) && n >= 1000 && n <= 90_000 ? n : 0;
}

/** Ping every intervalMs while open; returns stop(). intervalMs 0 = do nothing. */
export function startKeepalive(o: { intervalMs: number; isOpen: () => boolean; ping: () => void }): () => void {
  if (!o.intervalMs) return () => {};
  const t = setInterval(() => { if (o.isOpen()) { try { o.ping(); } catch { /* the close handler deals with a dead socket */ } } }, o.intervalMs);
  t.unref?.();
  return () => clearInterval(t);
}
