// Pure (unit-tested without any framework imports). The disposable list is a baseline, not exhaustive: extend it
// from real abuse in /admin/cyrus. Per-IP/device caps need request context and storage and are a separate step.
import { createHash } from "node:crypto";

const DISPOSABLE = new Set([
  "mailinator.com", "guerrillamail.com", "guerrillamail.net", "guerrillamail.org", "guerrillamail.biz", "guerrillamailblock.com", "sharklasers.com",
  "grr.la", "pokemail.net", "spam4.me", "10minutemail.com", "10minutemail.net", "20minutemail.com", "tempmail.com", "temp-mail.org", "temp-mail.io",
  "tempail.com", "tempmailo.com", "tmpmail.org", "tmpmail.net", "yopmail.com", "yopmail.net", "yopmail.fr", "trashmail.com", "trashmail.net",
  "trashmail.de", "getnada.com", "nada.email", "dispostable.com", "maildrop.cc", "throwawaymail.com", "fakeinbox.com", "mintemail.com", "mohmal.com",
  "emailondeck.com", "moakt.com", "mailnesia.com", "inboxkitten.com", "burnermail.io", "mytemp.email", "tempinbox.com", "discard.email", "mailcatch.com",
  "spamgourmet.com", "33mail.com", "getairmail.com", "mail.tm", "1secmail.com", "1secmail.net", "emailfake.com", "fakemail.net", "tempr.email",
  "dropmail.me", "harakirimail.com", "mailpoof.com", "mvrht.net", "my10minutemail.com", "owlymail.com", "spambox.us", "tafmail.com", "emltmp.com",
]);

const domainOf = (email: string): string => email.trim().toLowerCase().split("@")[1] ?? "";

/** True for known throwaway-inbox domains and their subdomains. */
export function isDisposableEmail(email: string): boolean {
  const d = domainOf(email);
  if (!d) return false;
  const parts = d.split(".");
  for (let i = 0; i < parts.length - 1; i++) if (DISPOSABLE.has(parts.slice(i).join("."))) return true;
  return false;
}

/** One identity per inbox: lowercase, drop +tags, and for Gmail also drop dots and map googlemail.com -> gmail.com. */
export function normalizeEmail(email: string): string {
  const e = email.trim().toLowerCase();
  const at = e.lastIndexOf("@");
  if (at < 1) return e;
  let local = e.slice(0, at).split("+")[0];
  let domain = e.slice(at + 1);
  if (domain === "googlemail.com") domain = "gmail.com";
  if (domain === "gmail.com") local = local.replace(/\./g, "");
  return `${local}@${domain}`;
}

export type StarterEligibility = { ok: true; key: string } | { ok: false; reason: "no_email" | "disposable" };

/** Whether this email may receive the starter grant, and the stable dedupe key (hash of the normalized email). */
export function starterEligibility(email: string | null | undefined): StarterEligibility {
  if (!email || !email.includes("@")) return { ok: false, reason: "no_email" };
  if (isDisposableEmail(email)) return { ok: false, reason: "disposable" };
  return { ok: true, key: createHash("sha256").update(normalizeEmail(email)).digest("hex").slice(0, 32) };
}
